-- ============================================================
-- B'SEDER — MySQL Schema v1
-- ============================================================
-- Charset: utf8mb4 supports full Unicode including Hebrew characters.
-- All timestamps use DATETIME(3) = millisecond precision UTC.
-- Soft deletes: rows are never physically deleted; deleted_at is set instead.
-- IDs: CHAR(36) UUIDs generated by the application (UUID() or crypto.randomUUID()).
-- ============================================================
SET NAMES utf8mb4;
SET time_zone = '+00:00';

-- ─────────────────────────────────────────────────────────────────────────────
-- SCHEMA MIGRATIONS
-- Tracks which migration scripts have been applied so we never run one twice.
-- Each migration file inserts its version string here on completion.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE schema_migrations (
  version    VARCHAR(64) NOT NULL,            -- e.g. "20260401_001_initial"
  applied_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (version)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ─────────────────────────────────────────────────────────────────────────────
-- USERS
-- One row per registered account. Soft-deleted users are kept so their goals
-- and assignments remain queryable for audit and potential account recovery.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE users (
  id                  CHAR(36)     NOT NULL,  -- UUID primary key
  email               VARCHAR(320) NOT NULL,  -- RFC 5321 max length; must be unique
  display_name        VARCHAR(100) NULL,      -- how the user wants to be addressed in the UI
  password_hash       VARCHAR(255) NULL,      -- bcrypt hash; NULL = OAuth-only account (no password)
  avatar_url          VARCHAR(500) NULL,      -- URL to profile photo (S3 / Cloudflare R2 / CDN)
  -- Subscription: cached here for fast reads on every request.
  -- The subscriptions table holds the full billing history; this field is
  -- updated whenever a subscription event comes in from Stripe.
  subscription_status ENUM('free','pro')      NOT NULL DEFAULT 'free',
  created_at          DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at          DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  deleted_at          DATETIME(3)  NULL,      -- soft delete: set when account is closed
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_email  (email),
  KEY        idx_users_deleted (deleted_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ─────────────────────────────────────────────────────────────────────────────
-- SUBSCRIPTIONS
-- Full billing history. One active row per user at most; prior rows are kept
-- for receipts and audit. Integrates with Stripe — store their IDs so we can
-- look up invoices, cancel, or reactivate directly via the Stripe API.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE subscriptions (
  id                     CHAR(36)    NOT NULL,
  user_id                CHAR(36)    NOT NULL,
  plan                   ENUM('free','pro')                                        NOT NULL,
  status                 ENUM('active','trialing','past_due','canceled','expired') NOT NULL,
  stripe_customer_id     VARCHAR(64) NULL,     -- Stripe cus_xxx — links user to Stripe customer
  stripe_subscription_id VARCHAR(64) NULL,     -- Stripe sub_xxx — the active subscription object
  trial_ends_at          DATETIME(3) NULL,     -- when the trial period ends (NULL = no trial)
  current_period_start   DATETIME(3) NULL,     -- start of the current billing cycle
  current_period_end     DATETIME(3) NULL,     -- end of the current billing cycle / next renewal
  canceled_at            DATETIME(3) NULL,     -- when the user canceled (subscription may run until period_end)
  created_at             DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at             DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_subscriptions_user   (user_id),
  KEY idx_subscriptions_stripe (stripe_subscription_id),
  CONSTRAINT fk_subscriptions_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ─────────────────────────────────────────────────────────────────────────────
-- SESSIONS
-- Login sessions for authenticated users. token_hash stores a SHA-256 of the
-- actual session token so we never keep the raw token in the DB.
-- Used by NextAuth.js or a custom auth layer.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE sessions (
  id         CHAR(36)    NOT NULL,
  user_id    CHAR(36)    NOT NULL,
  token_hash CHAR(64)    NOT NULL,    -- SHA-256 hex of the bearer token
  expires_at DATETIME(3) NOT NULL,    -- session is invalid after this time
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_sessions_token  (token_hash),
  KEY        idx_sessions_user    (user_id),
  KEY        idx_sessions_expires (expires_at),  -- used by the cleanup job
  CONSTRAINT fk_sessions_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ─────────────────────────────────────────────────────────────────────────────
-- LOCATIONS
-- Shared location table used for zmanim (halachic times) calculation.
-- latitude + longitude + timezone together determine zmanim for any date.
--
-- Two kinds of rows live here:
--   is_preset = 1 → shipped with the app; read-only; created_by is NULL
--   is_preset = 0 → user-created custom location; created_by = that user's id
--
-- Only cities/communities with significant Jewish populations are preset.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE locations (
  id          CHAR(36)     NOT NULL,
  name        VARCHAR(255) NOT NULL,   -- display name, e.g. "Brooklyn, NY"
  latitude    DECIMAL(9,6) NOT NULL,   -- degrees N/S (negative = south)
  longitude   DECIMAL(9,6) NOT NULL,   -- degrees E/W (negative = west)
  timezone    VARCHAR(64)  NOT NULL,   -- IANA tz string, e.g. "America/New_York"
  is_preset   TINYINT(1)   NOT NULL DEFAULT 0,  -- 1 = system preset, 0 = user-created
  created_by  CHAR(36)     NULL,       -- NULL for presets; user id for custom locations
  created_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  deleted_at  DATETIME(3)  NULL,       -- soft-delete for user-created locations
  PRIMARY KEY (id),
  KEY idx_locations_preset     (is_preset),
  KEY idx_locations_created_by (created_by),
  CONSTRAINT fk_locations_creator FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

