-- ─────────────────────────────────────────────────────────────────────────────
-- USER PREFERENCES
-- One row per user, created on signup with sensible defaults.
-- All calendar display settings live here rather than on the user row,
-- so the user row stays lean and auth-fast.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE user_preferences (
  user_id                        CHAR(36)   NOT NULL,           -- 1:1 with users
  location_id                    CHAR(36)   NULL,               -- FK to locations; NULL until user sets it
  time_format                    ENUM('12h','24h')           NOT NULL DEFAULT '12h',
  show_hebrew_dates              TINYINT(1) NOT NULL DEFAULT 1,  -- show Hebrew date below Gregorian
  week_starts_on                 TINYINT(1) NOT NULL DEFAULT 0,  -- 0 = Sunday, 1 = Monday
  default_view                   ENUM('month','week','day')  NOT NULL DEFAULT 'week',
  show_parsha                    TINYINT(1) NOT NULL DEFAULT 1,  -- show weekly Torah portion on Shabbos
  show_rosh_chodesh              TINYINT(1) NOT NULL DEFAULT 1,  -- highlight Rosh Chodesh days
  show_omer                      TINYINT(1) NOT NULL DEFAULT 1,  -- show Omer count during the Omer period
  show_modern_holidays           TINYINT(1) NOT NULL DEFAULT 0,  -- show Yom HaAtzmaut, Yom HaShoah, etc.
  show_outside_month_days        TINYINT(1) NOT NULL DEFAULT 1,  -- show faded days from adjacent months
  havdalah_opinion               ENUM('tzeit-8_5','42','50','72') NOT NULL DEFAULT 'tzeit-8_5',
  -- tzeit-8_5 = nightfall at 8.5 degrees below horizon (Geonim / most common)
  -- 42/50/72 = fixed minutes after sunset (various Ashkenazic opinions)
  timeline_snap_mins             TINYINT    NOT NULL DEFAULT 15, -- drag-snap granularity: 5/15/30/60
  timeline_default_duration_mins SMALLINT   NOT NULL DEFAULT 30, -- default block length: 15/30/45/60/90/120
  updated_at                     DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (user_id),
  CONSTRAINT fk_prefs_user     FOREIGN KEY (user_id)     REFERENCES users     (id) ON DELETE CASCADE,
  CONSTRAINT fk_prefs_location FOREIGN KEY (location_id) REFERENCES locations (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ─────────────────────────────────────────────────────────────────────────────
-- TAGS
-- User-defined labels (e.g. "Torah", "Health", "Work") that can be attached
-- to any goal for filtering and grouping. Each user manages their own tag set.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE tags (
  id         CHAR(36)     NOT NULL,
  user_id    CHAR(36)     NOT NULL,
  name       VARCHAR(100) NOT NULL,   -- tag label, e.g. "Learning"
  color      CHAR(7)      NULL,       -- hex color string, e.g. "#3b82f6"
  created_at DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  deleted_at DATETIME(3)  NULL,       -- soft delete
  PRIMARY KEY (id),
  UNIQUE KEY uq_tags_user_name (user_id, name),  -- no duplicate names per user
  CONSTRAINT fk_tags_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ─────────────────────────────────────────────────────────────────────────────
-- GOALS
-- The core entity. A goal represents something the user wants to do on a
-- recurring (daily/weekly/monthly/yearly) or one-time basis.
--
-- Two fundamental types:
--   binary     = done / not done each period (e.g. "Go to minyan")
--   quantified = X units per period (e.g. "Learn 10 pages/week")
--
-- Parent-child hierarchy: a goal can have a parent_goal_id pointing to another
-- goal in this same table. Example: "Run a marathon" (one-time, yearly) is the
-- parent of "Run 3x/week" (binary, weekly). Depth is unlimited but UI limits to 2.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE goals (
  id                  CHAR(36)     NOT NULL,
  user_id             CHAR(36)     NOT NULL,
  parent_goal_id      CHAR(36)     NULL,      -- self-referencing FK; NULL = top-level goal

  title               VARCHAR(500) NOT NULL,
  cadence             ENUM('one-time','yearly','monthly','weekly','daily') NOT NULL,
  status              ENUM('ongoing','paused','done','archived')           NOT NULL DEFAULT 'ongoing',
  type                ENUM('binary','quantified')                          NOT NULL,

  -- Quantified goal fields
  target              INT          NULL,      -- obligation per period, e.g. 10 (pages/week); NULL for binary
  target_unit         VARCHAR(100) NULL,      -- unit label shown in the UI, e.g. "pages", "daf", "km"
  backlog             INT          NOT NULL DEFAULT 0,  -- accumulated missed units carried forward

  -- Planning behaviour
  no_getting_ahead    TINYINT(1)   NOT NULL DEFAULT 0,
  -- When 1: the user cannot plan more units in a period than target + backlog.
  -- Prevents assigning all 10 pages on Monday even if the goal says spread across Thu+Fri.
  if_unfinished       ENUM('forgive','backlog','track-failure','kill-streak') NULL,
  -- forgive       = period closes clean; missed units disappear
  -- backlog       = missed units accumulate in the backlog field and carry forward
  -- track-failure = missed periods are counted as failures (streak broken)
  -- kill-streak   = one missed period ends the goal entirely
  preferred_month_day VARCHAR(10)  NULL,
  -- For monthly goals: where in the month to auto-place.
  -- Values: "first", "last", or a number "1" through "31"
  lock_in_days        TINYINT(1)   NOT NULL DEFAULT 0,
  -- When 1: the goal cannot be dragged to a different day. Fixed to its scheduled day(s).
  adhoc               TINYINT(1)   NOT NULL DEFAULT 0,
  -- When 1: created via the quick "+ Add task" input. Does not appear in the goal tray.

  -- Halachic time window (daily goals only)
  starts_at           VARCHAR(100) NULL,      -- zmanim period key after which the goal becomes active, e.g. "Netz HaChama"
  expires_at          VARCHAR(100) NULL,      -- zmanim period key after which the goal is dimmed, e.g. "Chatzot"

  -- Lifecycle dates
  start_date          DATE         NULL,      -- first day this goal counts; NULL = counts from creation
  end_date            DATE         NULL,      -- last day this goal counts (recurring); NULL = no end
  due_date            DATE         NULL,      -- hard deadline for one-time goals
  end_after_periods   INT          NULL,      -- alternative end condition: stop after N completed periods

  -- Audit timestamps
  created_at          DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at          DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  completed_at        DATETIME(3)  NULL,      -- set when status changes to 'done'
  paused_at           DATETIME(3)  NULL,      -- set when status changes to 'paused'
  archived_at         DATETIME(3)  NULL,      -- set when status changes to 'archived'
  deleted_at          DATETIME(3)  NULL,      -- soft delete

  PRIMARY KEY (id),
  KEY idx_goals_user    (user_id),
  KEY idx_goals_parent  (parent_goal_id),
  KEY idx_goals_cadence (cadence),
  KEY idx_goals_status  (status),
  KEY idx_goals_deleted (deleted_at),
  CONSTRAINT fk_goals_user   FOREIGN KEY (user_id)        REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_goals_parent FOREIGN KEY (parent_goal_id) REFERENCES goals (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ─────────────────────────────────────────────────────────────────────────────
-- GOAL ACTIVE DAYS
-- Which days of the week a weekly goal is active on.
-- Replaces the activeDays: string[] array that currently lives on the Goal object.
-- One row per (goal, day) pair. The composite primary key enforces uniqueness.
--
-- day_of_week integer mapping: 0=Sun 1=Mon 2=Tue 3=Wed 4=Thu 5=Fri 6=Sat
-- Example: a goal active on Thu+Fri has two rows: (goal_id, 4) and (goal_id, 5)
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE goal_active_days (
  goal_id     CHAR(36) NOT NULL,
  day_of_week TINYINT  NOT NULL,  -- 0=Sun, 1=Mon, 2=Tue, 3=Wed, 4=Thu, 5=Fri, 6=Sat
  PRIMARY KEY (goal_id, day_of_week),
  CONSTRAINT fk_active_days_goal FOREIGN KEY (goal_id) REFERENCES goals (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ─────────────────────────────────────────────────────────────────────────────
-- GOAL EXCLUSIONS
-- Jewish holidays on which a goal does NOT count toward its obligation.
-- Stored as individual holiday keys (e.g. "Yom_Kippur", "Chol_HaMoed_Pesach").
-- When a user selects a category like "Yom Tov", the app expands it to all
-- individual keys in that category before writing here. This keeps queries simple.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE goal_exclusions (
  goal_id     CHAR(36)     NOT NULL,
  holiday_key VARCHAR(100) NOT NULL,  -- matches keys in HOLIDAY_GROUPS (holiday-catalog.ts)
  PRIMARY KEY (goal_id, holiday_key),
  CONSTRAINT fk_exclusions_goal FOREIGN KEY (goal_id) REFERENCES goals (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ─────────────────────────────────────────────────────────────────────────────
-- GOAL TAGS  (junction table)
-- Many-to-many: a goal can have many tags; a tag can be on many goals.
-- Deleting a goal removes all its tag associations. Deleting a tag does the same.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE goal_tags (
  goal_id CHAR(36) NOT NULL,
  tag_id  CHAR(36) NOT NULL,
  PRIMARY KEY (goal_id, tag_id),
  CONSTRAINT fk_goal_tags_goal FOREIGN KEY (goal_id) REFERENCES goals (id) ON DELETE CASCADE,
  CONSTRAINT fk_goal_tags_tag  FOREIGN KEY (tag_id)  REFERENCES tags  (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ─────────────────────────────────────────────────────────────────────────────
-- GOAL MILESTONES
-- Named checkpoints on one-time / project goals. Cosmetic only — checking one
-- off does not change goal.target or progress math. They are visual markers on
-- the progress bar (e.g. "Finish Mesechta Brachos" at page 64 of 192).
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE goal_milestones (
  id            CHAR(36)     NOT NULL,
  goal_id       CHAR(36)     NOT NULL,
  label         VARCHAR(500) NOT NULL,    -- milestone name shown in the UI
  marker_amount INT          NULL,        -- unit count where this milestone sits on the bar
  sort_order    SMALLINT     NOT NULL DEFAULT 0,  -- user-controlled order within the goal
  completed_at  DATETIME(3)  NULL,        -- when the user checked it off; NULL = not done
  created_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at    DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  deleted_at    DATETIME(3)  NULL,
  PRIMARY KEY (id),
  KEY idx_milestones_goal (goal_id),
  CONSTRAINT fk_milestones_goal FOREIGN KEY (goal_id) REFERENCES goals (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ─────────────────────────────────────────────────────────────────────────────
-- GOAL PERIOD LEDGER
-- One row per goal per period. Written when a period opens (or on first
-- assignment within a period) and updated as the period progresses.
-- On period close: backlog_out = MAX(0, target_amount - completed_amount)
-- Next period: backlog_in = prior period's backlog_out.
--
-- This is the clean solution to the backlog/rollover problem. Instead of
-- re-scanning all history on every render, we materialize each period's
-- numbers here.
--
-- period_key format:
--   weekly  => "2026-03-22" (ISO date of the Sunday starting that week)
--   monthly => "2026-03"
--   yearly  => "2026"
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE goal_periods (
  id               CHAR(36)    NOT NULL,
  goal_id          CHAR(36)    NOT NULL,
  period_key       VARCHAR(20) NOT NULL,  -- identifies the period (see format above)
  target_amount    INT         NOT NULL,  -- effective obligation = goal.target + backlog_in
  planned_amount   INT         NOT NULL DEFAULT 0,  -- how many units have been scheduled (assigned)
  completed_amount INT         NOT NULL DEFAULT 0,  -- how many units have been marked done
  backlog_in       INT         NOT NULL DEFAULT 0,  -- shortfall carried in from the prior period
  backlog_out      INT         NOT NULL DEFAULT 0,  -- shortfall to carry into the next period (set on close)
  period_ended_at  DATETIME(3) NULL,      -- NULL = period is still open; set when period closes
  created_at       DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at       DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_goal_period (goal_id, period_key),
  CONSTRAINT fk_periods_goal FOREIGN KEY (goal_id) REFERENCES goals (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ─────────────────────────────────────────────────────────────────────────────
-- GOAL STATUS HISTORY  (append-only audit log)
-- Every time a goal's status changes (ongoing => paused, paused => done, etc.),
-- a row is inserted here. Rows are NEVER updated or deleted.
-- Enables: "when did I pause this?", streak calculation, failure rate reports.
-- from_status is NULL only for the initial 'ongoing' creation event.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE goal_status_history (
  id          CHAR(36)    NOT NULL,
  goal_id     CHAR(36)    NOT NULL,
  from_status ENUM('ongoing','paused','done','archived') NULL,   -- NULL = this is the creation event
  to_status   ENUM('ongoing','paused','done','archived') NOT NULL,
  changed_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  note        TEXT        NULL,  -- optional user-written reason for the change
  PRIMARY KEY (id),
  KEY idx_status_history_goal (goal_id),
  CONSTRAINT fk_status_history_goal FOREIGN KEY (goal_id) REFERENCES goals (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ─────────────────────────────────────────────────────────────────────────────
-- ASSIGNMENTS
-- The planning and completion record for a single goal on a single day.
-- An assignment is created when a user drags a goal to a day, or when a
-- recurring goal is explicitly scheduled (as opposed to the virtual "auto-show").
--
-- Key distinction: target_amount vs actual_amount
--   target_amount = how many units the user PLANNED for this session (e.g. 5 pages)
--   actual_amount = how many units the user ACTUALLY completed (entered at check-off)
--   These start equal; actual_amount can be less if the user did fewer than planned.
--
-- Auto-show suppression fields:
--   replaced_auto_date = if this assignment replaced a preferred-day auto-show,
--                        this is that preferred day's ISO date. Used to suppress
--                        the ghost auto-show from reappearing on that day.
--   skipped = 1 means this is a suppression record only — it renders nothing.
--             Created when deleting a moved assignment to keep the source day suppressed.
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE assignments (
  id                 CHAR(36)    NOT NULL,
  goal_id            CHAR(36)    NOT NULL,
  user_id            CHAR(36)    NOT NULL,  -- denormalized from goal for fast per-user queries
  date               DATE        NOT NULL,  -- the calendar day this assignment belongs to
  period_key         VARCHAR(20) NULL,      -- origin period; preserved when the assignment is moved to another day

  -- Planning
  target_amount      INT         NULL,      -- units planned for this session; NULL = binary (done/not done)
  scheduled_time     TIME        NULL,      -- HH:MM placement on the day timeline (optional)
  duration_mins      SMALLINT    NULL,      -- block length on the timeline in minutes

  -- Completion
  completed          TINYINT(1)  NOT NULL DEFAULT 0,   -- 0 = not done, 1 = done
  completed_at       DATETIME(3) NULL,      -- timestamp of when the user checked it off
  actual_amount      INT         NULL,      -- units actually completed (may differ from target_amount)

  -- Auto-show lifecycle
  replaced_auto_date DATE        NULL,      -- preferred-day ISO date that this assignment replaced
  skipped            TINYINT(1)  NOT NULL DEFAULT 0,
  -- When 1: this is a suppression-only record. No goal item is rendered.
  -- The row's date field points to the preferred day being suppressed.

  -- Audit
  created_at         DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at         DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  deleted_at         DATETIME(3) NULL,      -- soft delete (restores the auto-show on the calendar)

  PRIMARY KEY (id),
  KEY idx_assignments_goal      (goal_id),
  KEY idx_assignments_user_date (user_id, date),           -- primary query: "what's on my calendar today?"
  KEY idx_assignments_period    (goal_id, period_key),     -- period progress aggregation
  KEY idx_assignments_deleted   (deleted_at),
  CONSTRAINT fk_assignments_goal FOREIGN KEY (goal_id) REFERENCES goals (id) ON DELETE CASCADE,
  CONSTRAINT fk_assignments_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ─────────────────────────────────────────────────────────────────────────────
-- OMER COMPLETIONS
-- Simple record of which days the user counted the Omer.
-- No content beyond the date — the Omer count number is always computed
-- from the date (day N of the Omer = days since 2nd night of Pesach).
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE omer_completions (
  user_id        CHAR(36)    NOT NULL,
  completed_date DATE        NOT NULL,   -- the Gregorian date the user counted on
  counted_at     DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),  -- exact time they tapped "count"
  PRIMARY KEY (user_id, completed_date),
  CONSTRAINT fk_omer_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ─────────────────────────────────────────────────────────────────────────────
-- USER GOAL ORDER
-- Persists the user's drag-and-drop sort order of goals in the sidebar tray.
-- One row per (user, goal) pair. sort_order is a plain integer; to reorder,
-- update all affected rows (or use a float-based fractional indexing strategy).
-- ─────────────────────────────────────────────────────────────────────────────
CREATE TABLE user_goal_order (
  user_id    CHAR(36) NOT NULL,
  goal_id    CHAR(36) NOT NULL,
  sort_order INT      NOT NULL DEFAULT 0,  -- lower = higher in the list
  PRIMARY KEY (user_id, goal_id),
  KEY idx_goal_order_sort (user_id, sort_order),
  CONSTRAINT fk_goal_order_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT fk_goal_order_goal FOREIGN KEY (goal_id) REFERENCES goals (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
